-- Application schema. Authentication tables are generated by Better Auth.
CREATE TABLE profiles (
 user_id text PRIMARY KEY REFERENCES "user"(id) ON DELETE CASCADE,
 name varchar(80) NOT NULL DEFAULT '', birth_date date,
 location varchar(100) NOT NULL DEFAULT '', gender varchar(40) NOT NULL DEFAULT 'Prefiero no decirlo',
 bio varchar(500) NOT NULL DEFAULT '', interests text[] NOT NULL DEFAULT '{}',
 adventure_available boolean NOT NULL DEFAULT false,
 avatar_id uuid, cover_id uuid, published boolean NOT NULL DEFAULT false,
 created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(),
 CHECK (birth_date IS NULL OR birth_date <= (CURRENT_DATE - INTERVAL '18 years')::date)
);
CREATE INDEX profiles_discovery ON profiles(adventure_available, created_at DESC, user_id) WHERE published;
CREATE TABLE preferences (
 user_id text PRIMARY KEY REFERENCES "user"(id) ON DELETE CASCADE,
 min_age smallint NOT NULL DEFAULT 18, max_age smallint NOT NULL DEFAULT 99,
 gender varchar(40) NOT NULL DEFAULT 'Todos', location varchar(100) NOT NULL DEFAULT '',
 CHECK (min_age >= 18 AND max_age <= 99 AND min_age <= max_age)
);
CREATE TABLE profile_interests (
 user_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,
 target_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,
 kind text NOT NULL CHECK(kind IN ('like','pass')),
 created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,target_id), CHECK(user_id <> target_id)
);
CREATE INDEX profile_interests_incoming ON profile_interests(target_id,user_id) WHERE kind='like';
CREATE TABLE user_blocks (
 user_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,
 target_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,
 PRIMARY KEY(user_id,target_id), CHECK(user_id <> target_id)
);
CREATE TABLE conversations (
 id uuid PRIMARY KEY, user_low text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,
 user_high text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,
 kind text NOT NULL CHECK(kind IN ('match','direct')), created_at timestamptz NOT NULL DEFAULT now(),
 UNIQUE(user_low,user_high), CHECK(user_low < user_high)
);
CREATE INDEX conversations_low ON conversations(user_low,created_at DESC);
CREATE INDEX conversations_high ON conversations(user_high,created_at DESC);
CREATE TABLE messages (
 id uuid PRIMARY KEY, conversation_id uuid NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,
 sender_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,
 body varchar(4000) NOT NULL CHECK(length(trim(body)) > 0), created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX messages_history ON messages(conversation_id,created_at DESC,id DESC);
CREATE TABLE media_assets (
 id uuid PRIMARY KEY, owner_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,
 object_key text NOT NULL UNIQUE, mime varchar(80) NOT NULL,
 bytes integer NOT NULL CHECK(bytes > 0), width integer CHECK(width>0), height integer CHECK(height>0),
 created_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE profiles ADD FOREIGN KEY(avatar_id) REFERENCES media_assets(id);
ALTER TABLE profiles ADD FOREIGN KEY(cover_id) REFERENCES media_assets(id);
CREATE TABLE posts (
 id uuid PRIMARY KEY, author_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,
 media_id uuid NOT NULL REFERENCES media_assets(id), caption varchar(500) NOT NULL DEFAULT '',
 story boolean NOT NULL DEFAULT false, expires_at timestamptz,
 created_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz,
 CHECK ((story AND expires_at IS NOT NULL) OR (NOT story AND expires_at IS NULL))
);
CREATE INDEX posts_feed ON posts(created_at DESC,id DESC) WHERE deleted_at IS NULL AND NOT story;
CREATE INDEX posts_author ON posts(author_id,created_at DESC,id DESC) WHERE deleted_at IS NULL;
CREATE INDEX posts_stories ON posts(expires_at,author_id) WHERE deleted_at IS NULL AND story;
CREATE TABLE post_likes (
 post_id uuid NOT NULL REFERENCES posts(id) ON DELETE CASCADE,
 user_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, PRIMARY KEY(post_id,user_id)
);
CREATE TABLE post_saves (
 post_id uuid NOT NULL REFERENCES posts(id) ON DELETE CASCADE,
 user_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, PRIMARY KEY(post_id,user_id)
);
CREATE INDEX saves_user ON post_saves(user_id,post_id);
CREATE TABLE comments (
 id uuid PRIMARY KEY, post_id uuid NOT NULL REFERENCES posts(id) ON DELETE CASCADE,
 author_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,
 body varchar(500) NOT NULL CHECK(length(trim(body))>0), created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX comments_post ON comments(post_id,created_at,id);
CREATE TABLE review_invitations (
 id uuid PRIMARY KEY, owner_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,
 recipient_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(),
 UNIQUE(owner_id,recipient_id), CHECK(owner_id <> recipient_id)
);
CREATE TABLE reviews (
 id uuid PRIMARY KEY, invitation_id uuid NOT NULL UNIQUE REFERENCES review_invitations(id),
 body varchar(600) NOT NULL CHECK(length(trim(body))>0), stars smallint NOT NULL CHECK(stars BETWEEN 1 AND 5),
 created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE reports (
 id uuid PRIMARY KEY, reporter_id text NOT NULL REFERENCES "user"(id), review_id uuid REFERENCES reviews(id),
 reason varchar(500) NOT NULL DEFAULT 'Solicitud de revisión', created_at timestamptz NOT NULL DEFAULT now(),
 UNIQUE(reporter_id,review_id)
);
CREATE TABLE staff_roles (
 user_id text PRIMARY KEY REFERENCES "user"(id) ON DELETE CASCADE,
 role text NOT NULL CHECK(role IN ('admin','moderator','support'))
);
CREATE TABLE audit_events (
 id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, actor_id text REFERENCES "user"(id),
 action text NOT NULL, target_id text, created_at timestamptz NOT NULL DEFAULT now()
);
